/**
 * Reviewed response patterns for high-risk routes. These replies are NOT generated by the
 * language model. They follow common crisis-support practice: acknowledge, ask directly,
 * point to human help, avoid judgement and guarantees, and never claim the AI is monitoring
 * or contacting anyone. They must be reviewed by a qualified clinician before any public pilot.
 */
import type { RegionResources } from "@/lib/safety/resources";
import type { ScreenResult } from "@/lib/safety/policy";

function primaryLine(r: RegionResources) {
  const first = r.resources[0];
  if (!first) return "a local crisis line";
  if (first.phoneDisplay) return `${first.name} (${first.phoneDisplay})`;
  return `${first.name} (${first.url})`;
}

function emergencyLine(r: RegionResources) {
  return r.emergency.number ? `emergency services on ${r.emergency.number}` : "your local emergency number";
}

export function templateReply(template: NonNullable<ScreenResult["template"]>, r: RegionResources): string {
  switch (template) {
    case "immediate":
      return [
        "I'm really glad you told me. What you're describing sounds serious, and you deserve support from a real person right now.",
        `If you might act on these thoughts or you're in danger, please contact ${emergencyLine(r)} or ${primaryLine(r)} now. If you can, move away from anything you could use to hurt yourself and let someone you trust know you need them with you.`,
        "I'm an AI, so I can't contact anyone for you or check on you, but I can stay with you in this chat while you reach out. The help panel below has call and text links. Would you be willing to contact one of them now?",
      ].join("\n\n");
    case "concern":
      return [
        "Thank you for trusting me with this. It sounds like things feel really heavy right now.",
        "Can I ask you directly: are you having thoughts of ending your life or hurting yourself? Whatever your answer is, it's okay to say it here.",
        `You don't have to carry this alone. Talking with someone you trust, or a trained listener at ${primaryLine(r)}, can help. If you ever feel you might act on these thoughts, please contact ${emergencyLine(r)}. I'm here to keep talking too.`,
      ].join("\n\n");
    case "third_party":
      return [
        "It sounds like you're worried about someone you care about, and that's a lot to hold.",
        "If you think they're in immediate danger, contact " + emergencyLine(r) + " and try not to leave them alone. Otherwise, it can help to ask them directly and calmly whether they're thinking about suicide. Asking doesn't put the idea in their head, and listening without judgement matters more than having the right words.",
        `You can also contact ${primaryLine(r)} for guidance on supporting them, and please look after yourself as well. Would it help to think through what you might say to them?`,
      ].join("\n\n");
    case "harm_to_others":
      return [
        "It sounds like you're feeling a lot of anger or pressure right now. I'm not going to judge you for telling me.",
        `If you feel you might act on this, please put distance between yourself and the other person and contact ${emergencyLine(r)} or ${primaryLine(r)}, where someone can talk it through with you right away.`,
        "If it helps, we can slow things down together. What's happening right now that's brought this up?",
      ].join("\n\n");
    case "unsafe_environment":
      return [
        "I'm sorry you're dealing with this. Feeling unsafe with someone close to you is serious, and it isn't your fault.",
        `If you are in danger right now, contact ${emergencyLine(r)} if it's safe to do so. A trained listener at ${primaryLine(r)} can also help you think through options.`,
        "If you'd like, you can add a person you feel safe with in the Safety Centre. Only you choose who that is. Would it help to talk about what a safer next step could look like?",
      ].join("\n\n");
  }
}

/** Safe fallback used when a draft reply fails the output guard or generation fails. */
export function fallbackReply(r: RegionResources): string {
  return [
    "I want to make sure I respond to you carefully, and I don't have a good reply ready right now.",
    `If you're going through something difficult, you can reach ${primaryLine(r)} at any time. Would you like to tell me a bit more about what's on your mind?`,
  ].join(" ");
}
